// ─────────────────────────────────────────────────────────────────────────────
// BOQ planning exclusion helper — shared between importBoqItems (new rows) and
// backfillBoqPlanningInclude (one-time migration for existing rows).
// Returns true when a description matches a known non-production item type.
function isNonPlanningItem(description: string): boolean {
  const d = description.toLowerCase();
  return (
    d.includes("toll plaza") ||
    d.includes("toll booth") ||
    d.includes("toll gate") ||
    d.includes("provisional sum") ||
    d.includes("lump sum provision") ||
    d.includes("highway lighting") ||
    d.includes("solar lighting") ||
    d.includes("street lighting") ||
    d.includes("lamp post") ||
    d.includes("road furniture") ||
    d.includes("road sign") ||
    d.includes("signage") ||
    d.includes("ambulance") ||
    d.includes("first aid")
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// BOQ work-type helper — shared between importBoqItems and backfillBoqWorkType.
// Returns true when a description is a structure / point-location work item
// that should NOT be quantity-distributed linearly along the road axis.
function isStructureWorkItem(description: string): boolean {
  const d = description.toLowerCase();
  return (
    d.includes("bridge") ||
    d.includes("flyover") ||
    d.includes("viaduct") ||
    d.includes("culvert") ||
    d.includes("minor bridge") ||
    d.includes("major bridge") ||
    d.includes("abutment") ||
    d.includes("pier cap") ||
    d.includes("pier stem") ||
    d.includes("deck slab") ||
    d.includes("deck concrete") ||
    d.includes("wearing coat") ||
    d.includes("wearing course on bridge") ||
    d.includes("cd work") ||
    d.includes("cross drain") ||
    d.includes("retaining wall") ||
    d.includes("breast wall") ||
    d.includes("toe wall") ||
    d.includes("wing wall") ||
    d.includes("box drain") ||
    d.includes("catch pit") ||
    d.includes("catch water drain") ||
    d.includes("head wall") ||
    d.includes("protection wall")
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// RAW SQL CONVENTION — db.execute() usage
//
// When running raw SQL with db.execute(sql`...`) always follow these rules:
//
//   SELECT queries (multiple rows)
//               →  use execSelectRows<T>(result, context) to obtain the rows
//                  array.  node-postgres wraps the result in a QueryResult
//                  object ({ rows, rowCount, … }) that is NOT iterable, so
//                  array-destructuring or direct casting will silently return
//                  undefined instead of throwing.
//                  The helper throws loudly when the shape is unexpected.
//
//       ✓ const rows = execSelectRows<{ name: string }>(
//             await db.execute(sql`SELECT name FROM foo`),
//             "myMethod: list"
//           );
//       ✗ const [row] = await db.execute(sql`SELECT …`);  // always undefined!
//
//   SELECT queries (exactly one row required)
//               →  use execSelectOneRow<T>(result, context) when the query
//                  MUST return exactly one row (e.g. COUNT(*), lookup by PK).
//                  It extracts the rows array via execSelectRows then throws a
//                  descriptive error when zero rows come back, making silent
//                  "not found" bugs surface immediately instead of propagating
//                  as undefined downstream.
//
//       ✓ const row = execSelectOneRow<{ cnt: string }>(
//             await db.execute(sql`SELECT COUNT(*) AS cnt FROM foo`),
//             "myMethod: count"
//           );
//
//   DML (INSERT / UPDATE / DELETE / DDL)
//                   →  use execDmlRowCount(result, context?) to extract the
//                       affected-row count.  The helper accepts both the raw
//                       QueryResult from db.execute() and the typed result
//                       objects returned by Drizzle ORM's .delete()/.update(),
//                       throws loudly when the shape is unexpected, and
//                       eliminates scattered (result as { rowCount?: number })
//                       casts throughout the file.
//
//       ✓ const n = execDmlRowCount(
//             await db.execute(sql`DELETE FROM foo WHERE …`),
//             "myMethod: delete"
//           );
//       ✗ (result as { rowCount?: number }).rowCount ?? 0  // scattered cast
//
// All helpers are defined just above the DatabaseStorage class.
// ─────────────────────────────────────────────────────────────────────────────

// Task #434 — Maximum acceptable divergence between LDO flow-meter consumption
// and dip-stick-derived consumption within a single shift before the operator is
// warned. Expressed in litres. Adjust via this single constant if the threshold
// needs to be tuned without touching the comparison logic.
const LDO_DIVERGENCE_THRESHOLD_LITERS = 300;

// Task #490 — Convert an LDO material receipt quantity to litres using the same
// logic as convertLdoToL() on the frontend (PlantLdoFlowMeter.tsx).
function convertLdoQtyToLiters(quantity: number, uom: string): number {
  const u = uom.toLowerCase().trim();
  if (u === "liters" || u === "litres" || u === "l") return quantity;
  if (u === "kg") return quantity / LDO_DENSITY_KG_PER_LITER;
  if (u === "mt" || u === "ton" || u === "tons" || u === "t") return (quantity * 1000) / LDO_DENSITY_KG_PER_LITER;
  return quantity; // fallback: treat as litres
}

function isLdoOrDieselMaterial(name: string): boolean {
  const n = name.toUpperCase().trim();
  return n === "LDO" || n === "DIESEL";
}

