  previewLedgerForReassignment(opts: {
    materialId: number;
    fromPartyId: number;
    dateFrom?: string;
    dateTo?: string;
    transactionType?: string;
  }): Promise<{ id: number; date: string; transactionType: string; quantityIn: number | null; quantityOut: number | null; uom: string | null; notes: string | null }[]>;

